function cheapestCrossing(grid: number[][]): number {
  const m = grid.length, n = grid[0].length;
  const dirs = [[0, 1], [0, -1], [1, 0], [-1, 0]];
  const dist = Array.from({ length: m }, () => new Array<number>(n).fill(Infinity));
  dist[0][0] = 0;
  let changed = true;
  while (changed) {
    changed = false;
    for (let r = 0; r < m; r++) for (let c = 0; c < n; c++) {
      if (dist[r][c] === Infinity) continue;
      for (let d = 0; d < 4; d++) {
        const nr = r + dirs[d][0], nc = c + dirs[d][1];
        if (nr < 0 || nc < 0 || nr >= m || nc >= n) continue;
        const nd = dist[r][c] + (grid[r][c] === d + 1 ? 0 : 1);
        if (nd < dist[nr][nc]) { dist[nr][nc] = nd; changed = true; }
      }
    }
  }
  return dist[m - 1][n - 1];
}

