function cheapestCrossing(grid: number[][]): number {
  const m = grid.length, n = grid[0].length;
  const dirs = [[0, 1], [0, -1], [1, 0], [-1, 0]];
  const dist = new Array<number>(m * n).fill(Infinity);
  // deque as an array with a moving head; front pushes write below head
  // each cell is expanded once and pushes at most 4 entries
  const cap = 4 * m * n + 4;
  const dq = new Array<number>(2 * cap);
  const done = new Array<boolean>(m * n).fill(false);
  let head = cap, tail = cap;
  dist[0] = 0;
  dq[tail++] = 0;
  while (head < tail) {
    const cell = dq[head++];
    if (done[cell]) continue;
    done[cell] = true;
    const r = Math.floor(cell / n), c = cell % n;
    for (let d = 0; d < 4; d++) {
      const nr = r + dirs[d][0], nc = c + dirs[d][1];
      if (nr < 0 || nc < 0 || nr >= m || nc >= n) continue;
      const cost = grid[r][c] === d + 1 ? 0 : 1;
      const next = nr * n + nc;
      if (dist[cell] + cost < dist[next]) {
        dist[next] = dist[cell] + cost;
        if (cost === 0) dq[--head] = next; else dq[tail++] = next;
      }
    }
  }
  return dist[m * n - 1];
}

